function initSwitches(){ $$('.switch').forEach(sw=>sw.addEventListener('click',()=>{sw.classList.toggle('active'); const feed=$('#ideaFeed'); if(feed){ const only=sw.classList.contains('active'); $$('.idea-card',feed).forEach(c=>c.classList.toggle('hidden',only&&!c.dataset.video)); }})); }
function initMarketsNav(){ $$('[data-scroll]').forEach(btn=>btn.addEventListener('click',()=>{setActive($$('[data-scroll]'),btn); const el=document.getElementById(btn.dataset.scroll); if(el) el.scrollIntoView({behavior:'smooth',block:'start'}); })); }
function initChartControls(){ const status=$('#rangeStatus'); $$('[data-range]').forEach(btn=>btn.addEventListener('click',()=>{setActive($$('[data-range]'),btn); if(status) status.textContent=`AAPL ${btn.dataset.range} range · simulated live update`; const chart=$('.candles'); if(chart) chart.style.filter=`hue-rotate(${btn.dataset.range.length*12}deg)`;})); }
